mapper.insert:
INSERT INTO MOCK_CERTIFICATES (
    USER_ID, SERIAL_NO, PUBLIC_KEY, STATUS, ISSUED_AT, EXPIRES_AT
) VALUES (
             #{userId}, #{serialNo}, #{publicKey}, #{status}, SYSTIMESTAMP, #{expiresAt, jdbcType=TIMESTAMP}
         )

INSERT INTO MOCK_CHALLENGES (
    NONCE, USER_ID, ACCOUNT_NO, SCOPE, CONSENT_TEXT, USED_YN, EXPIRES_AT
) VALUES (
             #{nonce}, #{userId}, #{accountNo}, #{scope}, #{consentText}, #{usedYn}, #{expiresAt, jdbcType=TIMESTAMP}
         )

INSERT INTO MOCK_CONSENT_TOKENS (
    TOKEN_ID, USER_ID, ACCOUNT_NO, SCOPE, VALID_FROM, USED_YN, SIGNATURE_HASH, CREATED_AT, EXPIRES_AT
) VALUES (
             #{tokenId}, #{userId}, #{accountNo}, #{scope}, #{validFrom, jdbcType=TIMESTAMP},
             #{usedYn}, #{signatureHash}, SYSTIMESTAMP, #{expiresAt, jdbcType=TIMESTAMP}
         )
